            "status": 200,
            "body_contains": [
               "cart_id",
               "items",
               "subtotal_cents"
            ],
            "notes": "Cart data should be returned in JSON format"
         }
      },
      {
         "name": "Unauthorized Cart Retrieval",
         "description": "Attempt to retrieve cart data without authentication",
         "request": {
            "headers": {
               "Authorization": "Bearer <invalid_token>",
               "X-Cart-Token": "<invalid_token>"
            },
            "query": {},
            "path_params": {},
            "body": {}
         },
         "expected": {
            "status": 401,
            "body_contains": [
               "Unauthorized"
            ],
            "notes": "User should be redirected to login page"
         }
      },
      {
         "name": "Invalid Token Cart Retrieval",
         "description": "Attempt to retrieve cart data with invalid token",
         "request": {
            "headers": {
               "Authorization": "Bearer <invalid_token>",
               "X-Cart-Token": "<invalid_token>"
